Script used for backfill (with {{staffable}} attribute added to return from {{AssembledExternalApi}}):

{noformat}    const client = new AssembledExternalApi({
        host: "api.assembledhq.com",
        secure: true,
        path_prefix: "/v0",
        api_key: "<REDACTED>",
    });

    async function getPeopleBatch(ctx: Context, offset: number) {
        const resp = await client.getPeople(ctx, {offset, limit: 100});
        await sleep(500); // rate limits
        return Object.values(resp.people ?? {});
    }

    async function iterateOverPeople(
        ctx: Context,
        callback: (person: AssembledPerson) => Promise<void>,
    ): Promise<void> {
        let batch = await getPeopleBatch(ctx, 0);
        let countSoFar = 0;
        while (batch.length > 0) {
            for (const person of batch) {
                if (!person.staffable) {
                    console.log(`Skipping non-staffable person ${person.id} - ${person.email}`);
                    continue;
                }
                console.log(`Processing person ${person.id} - ${person.email}`);
                await callback(person);
            }
            countSoFar += batch.length;
            console.log(`Processed ${countSoFar} records by now, proceeding..`);
            batch = await getPeopleBatch(ctx, countSoFar);
        }
        console.log(`Processing finished - ${countSoFar} records total`);
    }

    ctest("do the thing", async (ctx) => {
        await iterateOverPeople(ctx, async (person) => {
            await client.updatePerson(ctx, person.id, {
                channels: [AssembledChannel.EMAIL, AssembledChannel.PHONE],
            });
            await sleep(500); // rate limits
        });
    });
{noformat}

